def P(oid,rx,ex=None):
    for x in lib.ORG[oid]['items']:
        if re.search(rx,x['title'] or '',re.I) and not (ex and re.search(ex,x['title'],re.I)) and (lib._num(x['price']) or 0)>1: return x['title'].strip(),lib._num(x['price'])
